<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>tears in rain</title>
<style>
  :root{
    --paper:#faf7ef;
    --ink:#2e2c27;
    --muted:#948d7e;
    --line:#d6cebd;
  }
  *{box-sizing:border-box;}
  html,body{margin:0;height:100%;}
  body{
    background:var(--paper);
    color:var(--ink);
    font-family:'Noto Serif SC','Spectral',"Songti SC",serif;
    -webkit-font-smoothing:antialiased;
    display:grid;place-items:center;
    padding:6vh 8vw;
    overflow:hidden;
    position:relative;
  }

  /* 手绘背景层: 五线谱行至中途向上弯起, 音符沿途脱杆成星; CSS 定位只对 <svg> 根元素有效. */
  .art{
    position:absolute;left:0;right:0;bottom:8%;
    width:100%;height:min(62vh,600px);
    pointer-events:none;z-index:1;
  }
  .art .l-ink{stroke:var(--ink);}
  .art .l-muted{stroke:var(--muted);}
  .art .f-ink{fill:var(--ink);}

  .poem{
    max-width:640px;
    text-align:center;
    position:relative;
    z-index:2;
    margin-bottom:26vh;
  }
  .poem .en{
    font-family:'Spectral',serif;
    font-style:italic;
    font-size:1.05rem;
    letter-spacing:.08em;
    line-height:2;
    color:var(--muted);
    margin-bottom:3.5vh;
  }
  .poem .cn{
    font-size:1.35rem;
    line-height:2.1;
    letter-spacing:.1em;
    margin:0;
  }
</style>
</head>
<body>

<!-- 手绘抖动滤镜: 低频噪声位移, 让所有路径带人手的不确定 -->
<svg width="0" height="0" style="position:absolute">
  <defs>
    <filter id="wobble" x="-5%" y="-5%" width="110%" height="110%">
      <feTurbulence type="fractalNoise" baseFrequency="0.012" numOctaves="2" seed="7" result="n"/>
      <feDisplacementMap in="SourceGraphic" in2="n" scale="7"/>
    </filter>
  </defs>
</svg>

<svg class="art" viewBox="0 0 1200 420" preserveAspectRatio="xMidYMax meet">
  <g filter="url(#wobble)" fill="none" stroke-width="2" stroke-linecap="round">
    <!-- 谱线: 左端平直, 右端扬起 -->
    <g class="l-ink" stroke-width="1.6">
      <path d="M80 330 C 320 328, 520 320, 700 270 C 830 234, 930 190, 1010 130"/>
      <path d="M80 308 C 320 306, 510 298, 680 252 C 810 218, 900 176, 970 118" opacity=".85"/>
      <path d="M80 286 C 320 284, 500 276, 660 234 C 790 202, 870 162, 930 106" opacity=".7"/>
      <path d="M80 264 C 320 262, 490 254, 640 216 C 770 186, 840 148, 890 96" opacity=".55"/>
      <path d="M80 242 C 320 240, 480 232, 620 198 C 750 170, 810 134, 850 88" opacity=".4"/>
    </g>
    <!-- 主星: 谱线尽头的圆与短芒 -->
    <circle class="l-ink" cx="1030" cy="100" r="14" stroke-width="1.8"/>
    <path class="l-ink" d="M1016 56 h 28 M1030 42 v 28" stroke-width="1.6"/>
    <!-- 谱上音符: 四分, 八分连音对, 二分 (空心), 双音和弦 -->
    <g stroke-width="1.8">
      <ellipse class="f-ink" cx="180" cy="300" rx="8" ry="6" transform="rotate(-15 180 300)"/>
      <path class="l-ink" d="M188 298 L 188 258"/>
      <ellipse class="f-ink" cx="278" cy="302" rx="8" ry="6" transform="rotate(-15 278 302)"/>
      <ellipse class="f-ink" cx="330" cy="297" rx="8" ry="6" transform="rotate(-15 330 297)"/>
      <path class="l-ink" d="M286 300 L 286 258 M338 295 L 338 253"/>
      <path class="l-ink" d="M286 258 L 338 253" stroke-width="3.4"/>
      <ellipse cx="430" cy="288" rx="8" ry="6" transform="rotate(-15 430 288)" fill="none" stroke="var(--ink)"/>
      <path class="l-ink" d="M438 286 L 438 246"/>
      <ellipse class="f-ink" cx="522" cy="290" rx="8" ry="6" transform="rotate(-15 522 290)"/>
      <ellipse class="f-ink" cx="530" cy="274" rx="8" ry="6" transform="rotate(-15 530 274)"/>
      <path class="l-ink" d="M538 272 L 538 232"/>
    </g>
    <!-- 演化链: 脱杆 → 点 → 星芒 -->
    <ellipse class="f-ink" cx="610" cy="256" rx="7" ry="5" transform="rotate(-25 610 256)" opacity=".8"/>
    <circle class="f-ink" cx="740" cy="216" r="4.5" opacity=".65"/>
    <circle class="f-ink" cx="850" cy="176" r="3.2" opacity=".5"/>
    <path class="l-ink" d="M918 138 h 12 M924 132 v 12" stroke-width="1.6" opacity=".8"/>
    <!-- 坠落的一个 -->
    <path class="l-muted" d="M700 290 l -18 40" stroke-width="1.8"/>
    <ellipse class="f-ink" cx="678" cy="338" rx="4.5" ry="4" opacity=".5"/>
  </g>
</svg>

<div class="poem">
  <p class="en">all those moments will be lost in time,<br>like tears in rain</p>
  <p class="cn">所有瞬间终将消逝于时间, 一如泪水没入雨中.</p>
</div>

<script>
  window.__PRESENTATION_STATE__ = { version:1, values:{} };
</script>
</body>
</html>

