import re, html
from html.parser import HTMLParser
src = open('2026-10-20-wordcount-cli-fail-closed.html', encoding='utf-8').read()
class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True); self.stack=[]; self.errs=[]
        self.void={'meta','link','br','hr','img','input','path','circle','ellipse','text','feTurbulence','feDisplacementMap'}
    def handle_starttag(self,t,a):
        if t not in self.void: self.stack.append((t,self.getpos()))
    def handle_endtag(self,t):
        if t in self.void: return
        if not self.stack: self.errs.append(('extra close',t,self.getpos())); return
        if self.stack[-1][0]!=t:
            self.errs.append(('mismatch',t,self.getpos(),self.stack[-1]))
            # pop until match
            for i in range(len(self.stack)-1,-1,-1):
                if self.stack[i][0]==t: del self.stack[i:]; break
        else: self.stack.pop()
p=P(); p.feed(src)
print('unclosed:', p.stack[:5])
print('errors:', p.errs[:10])
print('len:', len(src))
print('state object:', "__PRESENTATION_STATE__" in src)
print('verify path:', src.count('verify/round-1/report.md'))
for k in ['AC-001-1','AC-002-1','BR-001','R4S-1','R4P-2','--file -']:
    print(k, src.count(k))
PY
